// One request per test case. Signing happens later, right before each send, so every timestamp is exact.
// Change WEBHOOK_URL to your own instance.
const WEBHOOK_URL = 'https://YOUR-INSTANCE.app.n8n.cloud/webhook/ihm/events';
const runId = 'R' + Date.now().toString(36).toUpperCase();
const out = [];
for (const c of $input.all().map(i => i.json)) {
  const shop = c.shop_id;
  const m = c.mutation;
  const eventId = 'evt_' + runId + c.event_ref.toUpperCase();
  const body = {
    event_id: eventId,
    event_type: c.event_type,
    occurred_at: new Date(Date.now() - 30000).toISOString(),
    shop_id: shop,
    data: c.event_type === 'order.created'
      ? { order_id: 'ORD-' + c.event_ref.toUpperCase(), total: 49.9, currency: 'EUR' }
      : { customer_id: 'CUS-' + c.event_ref.toUpperCase(), email_opt_in: true }
  };
  let tsOffset = 0;
  let secretOf = shop;
  let contentType = 'application/json';
  let rawOverride = null;

  if (m === 'total_zero') body.data.total = 0;
  if (m === 'extra_field') body.data.gift_note = 'Happy birthday';
  if (m === 'unicode_name') body.data.display_name = 'Zoë Łukasz-Müller';
  if (m === 'ts_age_290') tsOffset = -290;
  if (m === 'ts_future_60') tsOffset = 60;
  if (m === 'ts_age_310') tsOffset = -310;
  if (m === 'ts_age_600') tsOffset = -600;
  if (m === 'ts_future_400') tsOffset = 400;
  if (m === 'wrong_secret') secretOf = 'wrong';
  if (m === 'other_shop_secret') secretOf = 'shop_mossbank';
  if (m === 'drop_event_id') delete body.event_id;
  if (m === 'drop_event_type') delete body.event_type;
  if (m === 'drop_occurred_at') delete body.occurred_at;
  if (m === 'drop_data') delete body.data;
  if (m === 'unknown_event_type') body.event_type = 'order.deleted';
  if (m === 'total_as_string') body.data.total = '49.90';
  if (m === 'total_negative') body.data.total = -5;
  if (m === 'optin_as_string') body.data.email_opt_in = 'yes';
  if (m === 'currency_lowercase') body.data.currency = 'eur';
  if (m === 'shop_mismatch') body.shop_id = 'shop_tallowick';
  if (m === 'bad_event_id') body.event_id = 'order-123';
  if (m === 'bad_date') body.occurred_at = 'yesterday';
  if (m === 'drop_customer_id') delete body.data.customer_id;
  if (m === 'changed_total') body.data.total = 999;
  if (m === 'invalid_json') {
    rawOverride = '{"event_id": "' + eventId + '", "event_type": "order.created",';
    // The n8n HTTP Request node re-encodes a non-JSON body sent as application/json,
    // so the broken body is sent as text/plain to keep the bytes exactly as signed.
    contentType = 'text/plain';
  }

  out.push({ json: { ...c, run_id: runId, test_tag: runId + ':' + c.case_id, url: WEBHOOK_URL,
    body_signed: rawOverride !== null ? rawOverride : JSON.stringify(body),
    body_pretty: JSON.stringify(body, null, 2),
    ts_offset: tsOffset, secret_of: secretOf, content_type: contentType,
    replay_key: shop + ':' + c.event_ref } });
}
return out;

// A case passes only if the HTTP status, the logged outcome and the stored/not stored result all match.
// The loop ran once per case, so each run of 'Sign now' and 'Send to webhook' belongs to one case.
const n = $('Get test cases').all().length;
const cases = [];
const responses = [];
for (let i = 0; i < n; i++) {
  cases.push($('Sign now').all(0, i)[0].json);
  responses.push($('Send to webhook').all(0, i)[0].json);
}
const logs = $('Get log rows of this run').all().map(i => i.json).filter(r => r.test_run);
const events = $('Get stored events of this run').all().map(i => i.json).filter(r => r.test_run);
const runAt = new Date().toISOString();

return cases.map((c, idx) => {
  const res = responses[idx] || {};
  const status = res.statusCode;
  const myLogs = logs.filter(l => l.test_run === c.test_tag);
  const outcome = myLogs.length === 1 ? myLogs[0].outcome : (myLogs.length === 0 ? 'no log row' : myLogs.length + ' log rows');
  const stored = events.some(e => e.test_run === c.test_tag);
  const passed = status === c.expected_status && outcome === c.expected_outcome && stored === c.expected_stored;
  return { json: {
    run_id: c.run_id,
    run_at: runAt,
    suite: 'intake',
    case_id: c.case_id,
    what_it_tests: c.what_it_tests,
    expected: c.expected_status + ' ' + c.expected_outcome + (c.expected_stored ? ' stored' : ' not stored'),
    actual: status + ' ' + outcome + (stored ? ' stored' : ' not stored'),
    passed,
    detail: myLogs.length ? (myLogs[0].reason || '') : JSON.stringify(res.body || '').slice(0, 200)
  } };
});

const rows = $('Compare expected vs actual').all().map(i => i.json);
const failed = rows.filter(r => !r.passed);
return [{ json: { run_id: rows[0] && rows[0].run_id, cases: rows.length, passed: rows.length - failed.length, failed: failed.length, failures: failed.map(f => f.case_id + ': expected ' + f.expected + ', got ' + f.actual + ' (' + f.detail + ')') } }];

// Signs one request right before it is sent, the same way a real shop would.
// Signature = HMAC-SHA256(shop secret, "<timestamp>.<raw body>"). Secrets come from n8n Variables.
const crypto = require('crypto');
const SECRET = {
  shop_mossbank: $vars.IHM_SECRET_MOSSBANK,
  shop_quillmoor: $vars.IHM_SECRET_QUILLMOOR,
  shop_tallowick: $vars.IHM_SECRET_TALLOWICK,
  wrong: 'this-is-not-the-shop-secret'
};
const c = $input.first().json;
if (!SECRET[c.shop_id] && c.shop_id !== 'shop_unknown') throw new Error('Variable missing for ' + c.shop_id);

// remembers the first signed request per event, so a later case can replay it byte for byte
const store = $getWorkflowStaticData('global');
if (store.ihm_run !== c.run_id) { store.ihm_run = c.run_id; store.ihm_sent = {}; }

const m = c.mutation;
const ts = Math.floor(Date.now() / 1000) + c.ts_offset;
const secret = SECRET[c.secret_of] || 'unknown-shop-has-no-secret';
let raw = c.body_signed;
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(String(ts) + '.' + raw, 'utf8').digest('hex');
const headers = { 'Content-Type': c.content_type, 'X-IHM-Shop': c.shop_id, 'X-IHM-Timestamp': String(ts), 'X-IHM-Signature': signature };

if (m === 'tamper_body') raw = raw.replace('49.9', '4.99');
if (m === 'reformatted_body') raw = c.body_pretty;
if (m === 'tamper_timestamp') headers['X-IHM-Timestamp'] = String(ts - 30);
if (m === 'no_signature') delete headers['X-IHM-Signature'];
if (m === 'bad_sig_format') headers['X-IHM-Signature'] = signature.slice(3);
if (m === 'no_timestamp') delete headers['X-IHM-Timestamp'];
if (m === 'ts_not_number') headers['X-IHM-Timestamp'] = 'yesterday';
if (m === 'replay_exact') {
  const first = store.ihm_sent[c.replay_key];
  raw = first.raw;
  Object.assign(headers, first.headers);
}
if (!store.ihm_sent[c.replay_key]) store.ihm_sent[c.replay_key] = { raw, headers: { ...headers } };

headers['X-IHM-Test-Run'] = c.test_tag;
return [{ json: { ...c, headers, raw } }];
